/* Bitmap fonts of the board GUI, generated by tools/make_font.py (see font.c). */
#ifndef FONT_H
#define FONT_H

#include <stdint.h>

typedef struct {
  uint8_t width, height;   /* of the glyph bitmap */
  int8_t x_off, y_off;     /* of the bitmap from the pen position (y from the top of the line) */
  uint8_t advance;         /* pen advance in pixels */
  uint16_t bitmap_offset;  /* into font_t::bitmap, rows of ceil(width/8) bytes, MSB first */
} font_glyph_t;

typedef struct {
  uint8_t height, ascent;  /* line height and baseline from the top of the line */
  uint8_t first, last;     /* character codes covered */
  const font_glyph_t *glyphs;
  const uint8_t *bitmap;
} font_t;

extern const font_t font_tiny;  /* DejaVu Sans 11 px */
extern const font_t font_small;  /* DejaVu Sans 15 px */
extern const font_t font_large;  /* DejaVu Sans Bold 22 px */
extern const font_t font_huge;  /* DejaVu Sans Bold 44 px */
extern const font_t font_title;  /* DejaVu Sans Bold 14 px */
extern const font_t font_label;  /* DejaVu Sans Bold 10 px */

#endif
